INSERT INTO sat_questions (question_id, external_id, vault_id, disclosed_item_id, source, program, test_type, test_type_desc, domain, primary_class_cd, skill_cd, skill_desc, difficulty, score_band_range_cd, question_type, stimulus_html, stem_html, answer_options, correct_answer, answer_keys, rationale_html, correct_answer_extracted_from_rationale, image_count, parent_template_name, parent_template_id, template_cluster_id, template_cluster_name, origin, position, answer_style, section, raw_payload, created_date, updated_date) VALUES
    ($SATQ$96c720af$SATQ$, $SATQ$d0e7c085-65c6-4b10-80a4-be7a83cb792b$SATQ$::uuid, $SATQ$14e9ccfc-17dd-4be3-b4a1-c095e25b89f8$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<p>Atoms in a synchrotron, a type of circular particle accelerator, travel faster and faster until they <span aria-hidden="true">______</span><span class="sr-only">blank</span> a desired energy level, at which point they are diverted to collide with a target, smashing the atoms.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"b1bce187-fbf7-431f-8400-b7510d1fd441","content":"<p>will reach</p>"},{"id":"b920e398-cbc2-42c7-81c7-d864b4718b61","content":"<p>reach</p>"},{"id":"1b720374-4839-4de9-8cf6-08d6ab9a3995","content":"<p>had reached</p>"},{"id":"a1731372-f377-4dd5-a96e-f4c0b2f9cd9e","content":"<p>are reaching</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["b920e398-cbc2-42c7-81c7-d864b4718b61"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. The convention being tested is the use of verbs to express tense in a sentence. In this choice, the present tense verb &ldquo;reach&rdquo; is consistent with the present tense verbs &ldquo;travel&rdquo; and &ldquo;are diverted&rdquo; used to describe how atoms move through the synchrotron. </p><p>Choice A is incorrect because the future tense verb &ldquo;will reach&rdquo; is inconsistent with the present tense verbs used to describe how atoms move through the synchrotron. Though the atoms&rsquo; movement is a recurring action and &ldquo;will reach&rdquo; can also be used to indicate a habitual or recurring action, it creates a logical inconsistency in this sentence when paired with the present tense verbs &ldquo;travel&rdquo; and &ldquo;are diverted.&rdquo; Choice C is incorrect because the past perfect tense verb &ldquo;had reached&rdquo; is inconsistent with the present tense verbs used to describe how atoms move through the synchrotron. Choice D is incorrect because the present progressive tense verb &ldquo;are reaching&rdquo; is inconsistent with the present tense verbs used to describe how atoms move through the synchrotron. While both verbs occur in the present, the present progressive tense suggests that the action is currently in progress. This creates a logical inconsistency when paired with the present tense verbs &ldquo;travel&rdquo; and &ldquo;are diverted,&rdquo; which offer a general description of the tendencies of the atoms&rsquo; movement, rather than a description of an action that is currently in progress. </p>$SATQ$, false, 0, $SATQ$OSP-624-SEC$SATQ$, $SATQ$$SATQ$, $SATQ$cee77017-38e6-404f-a85a-96b4e65cc533$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"96c720af","external_id":"d0e7c085-65c6-4b10-80a4-be7a83cb792b","vaultid":"14e9ccfc-17dd-4be3-b4a1-c095e25b89f8","uId":"23d784fc-6cac-490e-96e9-75449375ad44","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":"<p>Atoms in a synchrotron, a type of circular particle accelerator, travel faster and faster until they <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> a desired energy level, at which point they are diverted to collide with a target, smashing the atoms.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"b1bce187-fbf7-431f-8400-b7510d1fd441","content":"<p>will reach</p>"},{"id":"b920e398-cbc2-42c7-81c7-d864b4718b61","content":"<p>reach</p>"},{"id":"1b720374-4839-4de9-8cf6-08d6ab9a3995","content":"<p>had reached</p>"},{"id":"a1731372-f377-4dd5-a96e-f4c0b2f9cd9e","content":"<p>are reaching</p>"}],"keys":["b920e398-cbc2-42c7-81c7-d864b4718b61"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. The convention being tested is the use of verbs to express tense in a sentence. In this choice, the present tense verb &ldquo;reach&rdquo; is consistent with the present tense verbs &ldquo;travel&rdquo; and &ldquo;are diverted&rdquo; used to describe how atoms move through the synchrotron. </p><p>Choice A is incorrect because the future tense verb &ldquo;will reach&rdquo; is inconsistent with the present tense verbs used to describe how atoms move through the synchrotron. Though the atoms&rsquo; movement is a recurring action and &ldquo;will reach&rdquo; can also be used to indicate a habitual or recurring action, it creates a logical inconsistency in this sentence when paired with the present tense verbs &ldquo;travel&rdquo; and &ldquo;are diverted.&rdquo; Choice C is incorrect because the past perfect tense verb &ldquo;had reached&rdquo; is inconsistent with the present tense verbs used to describe how atoms move through the synchrotron. Choice D is incorrect because the present progressive tense verb &ldquo;are reaching&rdquo; is inconsistent with the present tense verbs used to describe how atoms move through the synchrotron. While both verbs occur in the present, the present progressive tense suggests that the action is currently in progress. This creates a logical inconsistency when paired with the present tense verbs &ldquo;travel&rdquo; and &ldquo;are diverted,&rdquo; which offer a general description of the tendencies of the atoms&rsquo; movement, rather than a description of an action that is currently in progress. </p>","parenttemplatename":"OSP-624-SEC","parenttemplateid":"","templateclusterid":"cee77017-38e6-404f-a85a-96b4e65cc533","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959339,"updateDate":1691007959339}$SATQ$::jsonb, 1691007959339, 1691007959339),
    ($SATQ$96e5da01$SATQ$, $SATQ$68710ed9-7d5e-4481-a404-a05d65bf8a01$SATQ$::uuid, $SATQ$7681851c-f4a9-40f3-966e-a2493c80a4d7$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<p>The alga species <em>Chlorella&nbsp;vulgaris</em> is very efficient at making oxygen. For this reason, scientists are currently exploring ways to use this species in space. <em>C. vulgaris</em> might be used, for example, to build future biological air exchange systems that <span aria-hidden="true">______</span><span class="sr-only">blank</span> oxygen for astronauts.&nbsp;</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"42faf7ac-25a7-455f-bad9-fd535361f665","content":"<p>are producing</p>"},{"id":"4e747732-00fe-4381-b645-0c24515102f2","content":"<p>produced</p>"},{"id":"b7ae82d7-cb6d-412d-bd38-56d07df689eb","content":"<p>produce</p>"},{"id":"76939e6b-2953-4917-bc16-e50a9952d50c","content":"<p>have produced</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["b7ae82d7-cb6d-412d-bd38-56d07df689eb"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. The convention being tested is the use of verbs to express tense. Simple present tense verbs can be used to describe actions that tend to occur, including in a hypothetical or future scenario. In this case, the simple present tense verb &ldquo;produce&rdquo; indicates what the air exchange systems might be able to do in the future (produce oxygen for astronauts). </p><p>Choice A is incorrect. The present progressive tense verb &ldquo;are producing&rdquo; suggests that the oxygen is currently being produced, not that it might be produced in the future. Choice B is incorrect because the past tense verb &ldquo;produced&rdquo; suggests that the oxygen was produced in the past, not that it might be produced in the future. Choice D is incorrect because the present perfect tense verb &ldquo;have produced&rdquo; suggests that the oxygen has been produced from a point in the past up to the present, not that it might be produced in the future. </p>$SATQ$, false, 0, $SATQ$OSP-715-SEC$SATQ$, $SATQ$$SATQ$, $SATQ$784fbd8e-464e-436e-a0f2-4979eabc1630$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"96e5da01","external_id":"68710ed9-7d5e-4481-a404-a05d65bf8a01","vaultid":"7681851c-f4a9-40f3-966e-a2493c80a4d7","uId":"f8f028b2-5318-43b0-95b0-815f6fa9a7a5","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":"<p>The alga species <em>Chlorella&nbsp;vulgaris</em> is very efficient at making oxygen. For this reason, scientists are currently exploring ways to use this species in space. <em>C. vulgaris</em> might be used, for example, to build future biological air exchange systems that <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> oxygen for astronauts.&nbsp;</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"42faf7ac-25a7-455f-bad9-fd535361f665","content":"<p>are producing</p>"},{"id":"4e747732-00fe-4381-b645-0c24515102f2","content":"<p>produced</p>"},{"id":"b7ae82d7-cb6d-412d-bd38-56d07df689eb","content":"<p>produce</p>"},{"id":"76939e6b-2953-4917-bc16-e50a9952d50c","content":"<p>have produced</p>"}],"keys":["b7ae82d7-cb6d-412d-bd38-56d07df689eb"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. The convention being tested is the use of verbs to express tense. Simple present tense verbs can be used to describe actions that tend to occur, including in a hypothetical or future scenario. In this case, the simple present tense verb &ldquo;produce&rdquo; indicates what the air exchange systems might be able to do in the future (produce oxygen for astronauts). </p><p>Choice A is incorrect. The present progressive tense verb &ldquo;are producing&rdquo; suggests that the oxygen is currently being produced, not that it might be produced in the future. Choice B is incorrect because the past tense verb &ldquo;produced&rdquo; suggests that the oxygen was produced in the past, not that it might be produced in the future. Choice D is incorrect because the present perfect tense verb &ldquo;have produced&rdquo; suggests that the oxygen has been produced from a point in the past up to the present, not that it might be produced in the future. </p>","parenttemplatename":"OSP-715-SEC","parenttemplateid":"","templateclusterid":"784fbd8e-464e-436e-a0f2-4979eabc1630","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959348,"updateDate":1691007959348}$SATQ$::jsonb, 1691007959348, 1691007959348),
    ($SATQ$975eda7c$SATQ$, $SATQ$03651229-f680-4462-944f-a84b59b78759$SATQ$::uuid, $SATQ$47f194ad-2224-40c4-b95c-cc0f6e6173b2$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<p>For thousands of years, people in the Americas <span aria-hidden="true">______</span><span class="sr-only">blank</span> the bottle gourd, a large bitter fruit with a thick rind, to make bottles, other types of containers, and even musical instruments. Oddly, there is no evidence that any type of bottle gourd is native to the Western Hemisphere; either the fruit or its seeds must have somehow been carried from Asia or Africa.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"0040b7b6-a3ff-41ae-bd2d-75a7ba3bc513","content":"<p>to use</p>"},{"id":"17d079c0-052b-4a15-afa7-30c231e354ea","content":"<p>have used</p>"},{"id":"08d6a552-13a7-4496-83de-63c3bc94b724","content":"<p>having used</p>"},{"id":"e48e646d-183d-42da-93b5-64e5050c3cc2","content":"<p>using</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["17d079c0-052b-4a15-afa7-30c231e354ea"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. The convention being tested is finite and nonfinite verb forms within a sentence. A main clause requires a finite verb to perform the action of the subject (in this case, &ldquo;people in the Americas&rdquo;), and this choice supplies the finite past perfect tense verb &ldquo;have used&rdquo; to indicate what people in the Americas used the gourd for.&nbsp;</p><p>Choice A is incorrect because the nonfinite to-infinitive &ldquo;to use&rdquo; doesn&rsquo;t supply the main clause with a finite verb. Choice C is incorrect because the nonfinite participle &ldquo;having used&rdquo; doesn&rsquo;t supply the main clause with a finite verb. Choice D is incorrect because the nonfinite participle &ldquo;using&rdquo; doesn&rsquo;t supply the main clause with a finite verb. </p>$SATQ$, false, 0, $SATQ$OSP-628-SEC$SATQ$, $SATQ$$SATQ$, $SATQ$11aafab7-cb50-458b-9d70-45ff10a0767e$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"975eda7c","external_id":"03651229-f680-4462-944f-a84b59b78759","vaultid":"47f194ad-2224-40c4-b95c-cc0f6e6173b2","uId":"e751e8ef-7566-47f5-9001-2d4efa7ad531","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":"<p>For thousands of years, people in the Americas <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> the bottle gourd, a large bitter fruit with a thick rind, to make bottles, other types of containers, and even musical instruments. Oddly, there is no evidence that any type of bottle gourd is native to the Western Hemisphere; either the fruit or its seeds must have somehow been carried from Asia or Africa.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"0040b7b6-a3ff-41ae-bd2d-75a7ba3bc513","content":"<p>to use</p>"},{"id":"17d079c0-052b-4a15-afa7-30c231e354ea","content":"<p>have used</p>"},{"id":"08d6a552-13a7-4496-83de-63c3bc94b724","content":"<p>having used</p>"},{"id":"e48e646d-183d-42da-93b5-64e5050c3cc2","content":"<p>using</p>"}],"keys":["17d079c0-052b-4a15-afa7-30c231e354ea"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. The convention being tested is finite and nonfinite verb forms within a sentence. A main clause requires a finite verb to perform the action of the subject (in this case, &ldquo;people in the Americas&rdquo;), and this choice supplies the finite past perfect tense verb &ldquo;have used&rdquo; to indicate what people in the Americas used the gourd for.&nbsp;</p><p>Choice A is incorrect because the nonfinite to-infinitive &ldquo;to use&rdquo; doesn&rsquo;t supply the main clause with a finite verb. Choice C is incorrect because the nonfinite participle &ldquo;having used&rdquo; doesn&rsquo;t supply the main clause with a finite verb. Choice D is incorrect because the nonfinite participle &ldquo;using&rdquo; doesn&rsquo;t supply the main clause with a finite verb. </p>","parenttemplatename":"OSP-628-SEC","parenttemplateid":"","templateclusterid":"11aafab7-cb50-458b-9d70-45ff10a0767e","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959340,"updateDate":1691007959340}$SATQ$::jsonb, 1691007959340, 1691007959340),
    ($SATQ$97b62fab$SATQ$, $SATQ$1302875a-5271-4e0a-8ec6-526e0b4929e6$SATQ$::uuid, $SATQ$608a5f20-f8e0-4b99-b5da-b07495b14104$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<p>Smaller than poppy seeds, tardigrades are tiny, but they are tough. These minuscule animals can survive for thirty years without food or water, and <span aria-hidden="true">______</span><span class="sr-only">blank</span> can withstand extreme temperatures as low as minus 328 degrees and as high as 304 degrees Fahrenheit.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"70576821-befc-4141-87da-9017d75292c7","content":"<p>that</p>"},{"id":"8498e371-007f-4221-9c7d-b14a044c08d5","content":"<p>it</p>"},{"id":"81b46448-8cdb-4db7-9e4b-03081abf9afe","content":"<p>they</p>"},{"id":"855bf2d9-df9d-475d-9f03-fdfb57d26bfd","content":"<p>he</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["81b46448-8cdb-4db7-9e4b-03081abf9afe"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. The convention being tested is pronoun-antecedent agreement. The plural pronoun "they" agrees in number with the plural antecedent "animals," which refers to tardigrades.</p><p>Choice A is incorrect because the singular pronoun "that" doesn&rsquo;t agree in number with the plural antecedent "animals." Choice B is incorrect because the singular pronoun "it" doesn&rsquo;t agree in number with the plural antecedent "animals." Choice D is incorrect because the singular pronoun "he" doesn&rsquo;t agree in number with the plural antecedent "animals."</p>$SATQ$, false, 0, $SATQ$OSP-757-SEC$SATQ$, $SATQ$$SATQ$, $SATQ$3f248945-5ecc-494d-8cc6-2ab7a65227c4$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"97b62fab","external_id":"1302875a-5271-4e0a-8ec6-526e0b4929e6","vaultid":"608a5f20-f8e0-4b99-b5da-b07495b14104","uId":"689c7217-b593-4a15-bf54-6a37cf1b098e","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":"<p>Smaller than poppy seeds, tardigrades are tiny, but they are tough. These minuscule animals can survive for thirty years without food or water, and <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> can withstand extreme temperatures as low as minus 328 degrees and as high as 304 degrees Fahrenheit.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"70576821-befc-4141-87da-9017d75292c7","content":"<p>that</p>"},{"id":"8498e371-007f-4221-9c7d-b14a044c08d5","content":"<p>it</p>"},{"id":"81b46448-8cdb-4db7-9e4b-03081abf9afe","content":"<p>they</p>"},{"id":"855bf2d9-df9d-475d-9f03-fdfb57d26bfd","content":"<p>he</p>"}],"keys":["81b46448-8cdb-4db7-9e4b-03081abf9afe"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. The convention being tested is pronoun-antecedent agreement. The plural pronoun \"they\" agrees in number with the plural antecedent \"animals,\" which refers to tardigrades.</p><p>Choice A is incorrect because the singular pronoun \"that\" doesn&rsquo;t agree in number with the plural antecedent \"animals.\" Choice B is incorrect because the singular pronoun \"it\" doesn&rsquo;t agree in number with the plural antecedent \"animals.\" Choice D is incorrect because the singular pronoun \"he\" doesn&rsquo;t agree in number with the plural antecedent \"animals.\"</p>","parenttemplatename":"OSP-757-SEC","parenttemplateid":"","templateclusterid":"3f248945-5ecc-494d-8cc6-2ab7a65227c4","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959351,"updateDate":1691007959351}$SATQ$::jsonb, 1691007959351, 1691007959351),
    ($SATQ$97df6650$SATQ$, $SATQ$3bf78db0-3a62-4e52-addb-7eec43aeb7cc$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<p>The village of Panduyacu in Ecuador <span aria-hidden="true">______</span><span class="sr-only">blank</span> one of the rare places in the world located almost directly on the equator.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"f2821382-d013-4063-8fd1-6f40f48c9887","content":"<p>are being</p>"},{"id":"cb3ff713-8687-4b43-9172-de0e5db4ba55","content":"<p>have been</p>"},{"id":"e519aa3d-d545-4af8-a22e-38ecb96dc5df","content":"<p>is</p>"},{"id":"9c71cd99-4949-4e63-90f8-c691c3edd04c","content":"<p>are</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["e519aa3d-d545-4af8-a22e-38ecb96dc5df"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. The convention being tested is subject-verb agreement. The singular verb "is" agrees in number with the singular subject "village."</p><p>Choice A is incorrect because the plural verb "are being" doesn&rsquo;t agree in number with the singular subject "village." Choice B is incorrect because the plural verb "have been" doesn&rsquo;t agree in number with the singular subject "village." Choice D is incorrect because the plural verb "are" doesn&rsquo;t agree in number with the singular subject "village."</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"97df6650","external_id":"3bf78db0-3a62-4e52-addb-7eec43aeb7cc","vaultid":null,"uId":"573d49d9-360a-418f-ada3-c1524ee7f7a8","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"E","